class Resp:
    def __init__(self, status, body=None):
        self.status = status
        self.body = body

def server(method, path, body=None):
    LOG.append(f"{method} {path} body={body!r}")
    if method == "POST" and path == "/orders":
        # the route only exists WITH the trailing slash; the edge
        # redirects the slash-less spelling
        return Resp(301)
    if method == "GET" and path == "/orders/":
        return Resp(200, {"orders": []})
