            "zip": r["addr_postal_code"]}

nested = {"id": 1, "address": {"line1": "228 Park Ave", "city": "Winter Park",
                               "postal_code": "32789"}}
flat = {"id": 2, "addr_line1": "228 Park Ave", "addr_city": "Winter Park",
        "addr_postal_code": "32789"}

