import hashlib, hmac

SECRET = b"whsec_test_7"

def sign(ts, body):
    return hmac.new(SECRET, f"{ts}.".encode() + body, hashlib.sha256).hexdigest()

def handle(now, ts, body, signature, tolerance=300):
    if abs(now - ts) > tolerance:
        return f"REJECTED: event is {now - ts}s old (tolerance {tolerance}s)"
    if not hmac.compare_digest(sign(ts, body), signature):
        return "REJECTED: bad signature"
    return "accepted"

